import { apiRequest } from '../../../utils/apiClient';

const BASE = '/job-orders';

/**
 * What the job order form needs.
 * @returns {Promise<{ isTaxOn: boolean,
 *   settings: { isJobOrderNumberAutoGenerated, askCustomerAddress, useShortNamesOn, useShortNames },
 *   masters: Array<{ _id, name, shortName, isRequired, isMultiselectAllowed, defaultValueId, values }>,
 *   controls: Array, countries: Array<{ _id, name, taxName, interStateTaxLabel, postalCode, currency,
 *   states, cities, taxes, isTaxReady, defaultTaxId, businessStateId }> }>}
 */
export const getFormData = ({ signal } = {}) => apiRequest(`${BASE}/form-data`, { signal });

/** @returns {Promise<{ jobOrders: Array, pagination: Object }>} */
export const listJobOrders = ({ search, page, limit } = {}, { signal } = {}) => {
  const query = new URLSearchParams();
  if (search) query.set('search', search);
  if (page) query.set('page', page);
  if (limit) query.set('limit', limit);
  const qs = query.toString();
  return apiRequest(`${BASE}${qs ? `?${qs}` : ''}`, { signal });
};

/** @returns {Promise<{ jobOrder: Object }>} */
export const getJobOrder = (id, { signal } = {}) => apiRequest(`${BASE}/${id}`, { signal });

// With new images: multipart, the job order as JSON in "data" and the files in "images".
const withImages = (data, files) => {
  if (files.length === 0) return data;
  const body = new FormData();
  body.append('data', JSON.stringify(data));
  for (const file of files) body.append('images', file);
  return body;
};

/**
 * data: { jobOrderNumber?, customer: { countryId, stateId, cityId, postalCode, address },
 * masters: [{ masterId, valueIds }], controls: [{ controlId, text?, checked?, optionId? }], taxId }
 * files: new images (File[])
 * @returns {Promise<{ jobOrder: { _id, jobOrderNumber } }>}
 */
export const createJobOrder = (data, files = []) => apiRequest(BASE, { method: 'POST', body: withImages(data, files) });

/** Same as createJobOrder, plus data.keepImageIds: the saved images to keep (the rest are removed). */
export const updateJobOrder = (id, data, files = []) => apiRequest(`${BASE}/${id}`, { method: 'PUT', body: withImages(data, files) });

export const cancelJobOrder = (id) => apiRequest(`${BASE}/${id}`, { method: 'DELETE' });

export default {
  getFormData,
  listJobOrders,
  getJobOrder,
  createJobOrder,
  updateJobOrder,
  cancelJobOrder,
};
